      ["s-cerv", 300, 200, tt("Les vertèbres cervicales", "The cervical vertebrae", "Las vértebras cervicales", "Le vertebre cervicali", "Die Halswirbel", "頸椎", "الفقرات العنقية", "颈椎", "De halswervels", "As vértebras cervicais", "Halskotorna", "Шейные позвонки", "Kręgi szyjne", "경추"), tt("Dans l'encolure, de la tête jusqu'au garrot.", "In the neck, from the head to the withers.", "En el cuello, desde la cabeza hasta la cruz.", "Nell'incollatura, dalla testa fino al garrese.", "Im Hals, vom Kopf bis zum Widerrist.", "首の中、頭からき甲まで。", "في العنق، من الرأس حتى الحارك.", "位于颈部，从头部到鬐甲。", "In de hals, van het hoofd tot de schoft.", "No pescoço, da cabeça até a cernelha.", "I halsen, från huvudet till manken.", "В шее, от головы до холки.", "W szyi, od głowy do kłębu.", "목 안, 머리에서 기갑까지.")],
      ["s-dors", 620, 255, tt("Les vertèbres dorsales", "The thoracic vertebrae", "Las vértebras dorsales", "Le vertebre dorsali", "Die Brustwirbel", "胸椎", "الفقرات الظهرية", "胸椎", "De rugwervels", "As vértebras dorsais", "Bröstkotorna", "Грудные позвонки", "Kręgi piersiowe", "흉추"), tt("Du garrot jusqu'au rein, sous la selle.", "From the withers to the loins, under the saddle.", "Desde la cruz hasta los riñones, bajo la silla.", "Dal garrese fino ai lombi, sotto la sella.", "Vom Widerrist bis zur Lende, unter dem Sattel.", "き甲から腰まで、鞍の下。", "من الحارك حتى القَطَن، تحت السرج.", "从鬐甲到腰部，位于马鞍下方。", "Van de schoft tot de lendenen, onder het zadel.", "Da cernelha até o lombo, sob a sela.", "Från manken till ländryggen, under sadeln.", "От холки до поясницы, под седлом.", "Od kłębu do lędźwi, pod siodłem.", "기갑에서 허리까지, 안장 아래.")],
      ["s-cotes", 640, 430, tt("Les côtes", "The ribs", "Las costillas", "Le costole", "Die Rippen", "肋骨", "الأضلاع", "肋骨", "De ribben", "As costelas", "Revbenen", "Рёбра", "Żebra", "갈비뼈"), tt("Autour de la poitrine, rattachées aux vertèbres dorsales.", "Around the chest, attached to the thoracic vertebrae.", "Alrededor del pecho, unidas a las vértebras dorsales.", "Intorno al torace, attaccate alle vertebre dorsali.", "Rund um den Brustkorb, an den Brustwirbeln befestigt.", "胸のまわり、胸椎につながっている。", "حول الصدر، متصلة بالفقرات الظهرية.", "环绕胸部，连接在胸椎上。", "Rond de borst, vastgemaakt aan de rugwervels.", "À volta do peito, ligadas às vértebras dorsais.", "Runt bröstkorgen, fästa vid bröstkotorna.", "Вокруг грудной клетки, прикреплены к грудным позвонкам.", "Wokół klatki piersiowej, połączone z kręgami piersiowymi.", "가슴 둘레, 흉추에 붙어 있어요.")],
      ["s-lomb", 855, 280, tt("Les vertèbres lombaires", "The lumbar vertebrae", "Las vértebras lumbares", "Le vertebre lombari", "Die Lendenwirbel", "腰椎", "الفقرات القطنية", "腰椎", "De lendenwervels", "As vértebras lombares", "Ländkotorna", "Поясничные позвонки", "Kręgi lędźwiowe", "요추"), tt("Au rein, entre la dernière côte et le bassin.", "In the loins, between the last rib and the pelvis.", "En los riñones, entre la última costilla y la pelvis.", "Nei lombi, tra l'ultima costola e il bacino.", "In der Lende, zwischen der letzten Rippe und dem Becken.", "腰の部分、最後の肋骨と骨盤のあいだ。", "في منطقة القَطَن، بين آخر ضلع والحوض.", "位于腰部，在最后一根肋骨和骨盆之间。", "In de lendenen, tussen de laatste rib en het bekken.", "No lombo, entre a última costela e a bacia.", "I ländryggen, mellan sista revbenet och bäckenet.", "В пояснице, между последним ребром и тазом.", "W lędźwiach, między ostatnim żebrem a miednicą.", "허리 부분, 마지막 갈비뼈와 골반 사이.")],
      ["s-sacr", 940, 250, tt("Le sacrum", "The sacrum", "El sacro", "L'osso sacro", "Das Kreuzbein", "仙骨", "العجز", "荐骨", "Het heiligbeen", "O sacro", "Korsbenet", "Крестец", "Kość krzyżowa", "천골"), tt("En haut de la croupe, au-dessus du bassin.", "At the top of the croup, above the pelvis.", "En lo alto de la grupa, encima de la pelvis.", "In cima alla groppa, sopra il bacino.", "Oben auf der Kruppe, über dem Becken.", "尻の上部、骨盤の上。", "أعلى الكَفَل، فوق الحوض.", "位于臀部上方，在骨盆之上。", "Bovenaan het kruis, boven het bekken.", "No alto da garupa, acima da bacia.", "Högst upp på korset, ovanför bäckenet.", "В верхней части крупа, над тазом.", "W górnej części zadu, nad miednicą.", "엉덩이 윗부분, 골반 위.")],
      ["s-cocc", 1258, 450, tt("Les vertèbres coccygiennes", "The coccygeal vertebrae", "Las vértebras coccígeas", "Le vertebre coccigee", "Die Schwanzwirbel", "尾椎", "الفقرات العصعصية", "尾椎", "De staartwervels", "As vértebras coccígeas", "Svanskotorna", "Хвостовые позвонки", "Kręgi ogonowe", "미추"), tt("Dans la queue, jusqu'à son extrémité.", "In the tail, right to its tip.", "En la cola, hasta su extremo.", "Nella coda, fino alla sua estremità.", "Im Schweif, bis zu seinem Ende.", "尾の中、先端まで。", "في الذيل، حتى طرفه.", "位于尾部，一直到尾尖。", "In de staart, tot aan het uiteinde.", "Na cauda, até à sua ponta.", "I svansen, ända ut till spetsen.", "В хвосте, до самого его кончика.", "W ogonie, aż do jego końca.", "꼬리 안, 끝까지.")],
      ["s-omo", 500, 330, tt("L'omoplate", "The shoulder blade", "La escápula", "La scapola", "Das Schulterblatt", "肩甲骨", "لوح الكتف", "肩胛骨", "Het schouderblad", "A escápula", "Skulderbladet", "Лопатка", "Łopatka", "견갑골"), tt("En haut de l'épaule, à plat contre les côtes.", "At the top of the shoulder, lying flat against the ribs.", "En lo alto de la espalda, plana contra las costillas.", "In cima alla spalla, appoggiata contro le costole.", "Oben an der Schulter, flach an den Rippen.", "肩の上部、肋骨に沿って平らについている。", "أعلى الكتف، مسطّح على الأضلاع.", "位于肩部上方，平贴在肋骨上。", "Bovenaan de schouder, plat tegen de ribben.", "No alto do ombro, encostada às costelas.", "Högst upp på bogen, platt mot revbenen.", "В верхней части плеча, плоско прилегает к рёбрам.", "W górnej części barku, płasko przy żebrach.", "어깨 윗부분, 갈비뼈에 납작하게 붙어 있어요.")],
      ["s-hum", 425, 470, tt("L'humérus", "The humerus", "El húmero", "L'omero", "Das Oberarmbein", "上腕骨", "عظم العضد", "肱骨", "Het opperarmbeen", "O úmero", "Överarmsbenet", "Плечевая кость", "Kość ramienna", "상완골"), tt("Entre la pointe de l'épaule et le coude.", "Between the point of the shoulder and the elbow.", "Entre la punta de la espalda y el codo.", "Tra la punta della spalla e il gomito.", "Zwischen dem Buggelenk und dem Ellbogen.", "肩端と肘のあいだ。", "بين رأس الكتف والمرفق.", "位于肩端和肘部之间。", "Tussen de boeg en de elleboog.", "Entre a ponta do ombro e o cotovelo.", "Mellan bogleden och armbågen.", "Между плечевым суставом и локтем.", "Między stawem barkowym a łokciem.", "어깨 끝과 팔꿈치 사이.")],
      ["s-rad", 440, 615, tt("Le radius", "The radius", "El radio", "Il radio", "Die Speiche", "橈骨", "عظم الكعبرة", "桡骨", "Het spaakbeen", "O rádio", "Strålbenet", "Лучевая кость", "Kość promieniowa", "요골"), tt("Dans l'avant-bras, entre le coude et le genou.", "In the forearm, between the elbow and the knee.", "En el antebrazo, entre el codo y la rodilla.", "Nell'avambraccio, tra il gomito e il ginocchio.", "Im Unterarm, zwischen Ellbogen und Vorderknie.", "前腕の中、肘と腕節（前膝）のあいだ。", "في الساعد، بين المرفق والركبة.", "位于前臂，在肘部和腕部（马的“膝”）之间。", "In de onderarm, tussen de elleboog en de voorknie.", "No antebraço, entre o cotovelo e o joelho.", "I underarmen, mellan armbågen och framknät.", "В предплечье, между локтем и запястьем («коленом»).", "W przedramieniu, między łokciem a nadgarstkiem.", "앞팔 안, 팔꿈치와 무릎 사이.")],
      ["s-gen", 437, 715, tt("Les os du genou", "The knee bones", "Los huesos de la rodilla", "Le ossa del ginocchio", "Die Knochen des Vorderknies", "腕節（前膝）の骨", "عظام الركبة", "腕部（马的“膝”）的骨骼", "De botten van de voorknie", "Os ossos do joelho", "Benen i framknät", "Кости запястья («колена»)", "Kości nadgarstka", "무릎의 뼈"), tt("Au milieu de l'antérieur, entre l'avant-bras et le canon.", "In the middle of the foreleg, between the forearm and the cannon.", "En medio del anterior, entre el antebrazo y la caña.", "A metà dell'anteriore, tra l'avambraccio e lo stinco.", "In der Mitte des Vorderbeins, zwischen Unterarm und Röhrbein.", "前肢の中ほど、前腕と管のあいだ。", "في منتصف القائمة الأمامية، بين الساعد والمدماك.", "位于前肢中部，在前臂和炮骨之间。", "Halverwege het voorbeen, tussen de onderarm en de pijp.", "A meio do anterior, entre o antebraço e a canela.", "Mitt på frambenet, mellan underarmen och skenbenet.", "В середине передней ноги, между предплечьем и пястью.", "W połowie kończyny przedniej, między przedramieniem a nadpęciem.", "앞다리 중간, 앞팔과 관골 사이.")],
      ["s-bas", 440, 860, tt("Canon, boulet, paturon, couronne et pied", "Cannon, fetlock, pastern, coronet and foot", "Caña, menudillo, cuartilla, corona y casco", "Stinco, nodello, pastoia, corona e piede", "Röhrbein, Fesselgelenk, Fessel, Krone und Huf", "管、球節、繋、冠、蹄", "المدماك والعقدة والرسغ والتاج والحافر", "炮骨、球节、系部、蹄冠和蹄", "Pijp, kogel, koot, kroon en hoef", "Canela, boleto, quartela, coroa e casco", "Skenben, kotled, kota, krona och hov", "Пясть, путовый сустав, путо, венчик и копыто", "Nadpęcie, pęcina, kości pęcinowa, koronowa i kopytowa", "관골, 구절, 계부, 관부, 발굽"), tt("Du genou jusqu'au sabot.", "From the knee down to the hoof.", "Desde la rodilla hasta el casco.", "Dal ginocchio fino allo zoccolo.", "Vom Vorderknie bis zum Huf.", "腕節（前膝）から蹄まで。", "من الركبة حتى الحافر.", "从腕部一直到蹄。", "Van de voorknie tot de hoef.", "Do joelho até ao casco.", "Från framknät ner till hoven.", "От запястья («колена») до копыта.", "Od nadgarstka aż do kopyta.", "무릎에서 발굽까지.")],
      ["s-bass", 1060, 345, tt("Le bassin", "The pelvis", "La pelvis", "Il bacino", "Das Becken", "骨盤", "الحوض", "骨盆", "Het bekken", "A bacia", "Bäckenet", "Таз", "Miednica", "골반"), tt("Sous la croupe, de la hanche jusqu'à la pointe de la fesse.", "Under the croup, from the hip to the point of the buttock.", "Bajo la grupa, desde la cadera hasta la punta de la nalga.", "Sotto la groppa, dall'anca fino alla punta della natica.", "Unter der Kruppe, von der Hüfte bis zum Sitzbeinhöcker.", "尻の下、腰角から坐骨端まで。", "تحت الكَفَل، من الورك حتى طرف الإلية.", "位于臀部下方，从髋部到臀端。", "Onder het kruis, van de heup tot de zitbeenknobbel.", "Sob a garupa, da anca até à ponta da nádega.", "Under korset, från höften till sittbensknölen.", "Под крупом, от маклока до седалищного бугра.", "Pod zadem, od biodra do guza kulszowego.", "엉덩이 아래, 고관절에서 궁둥이 끝까지.")],
      ["s-fem", 1025, 420, tt("Le fémur", "The femur", "El fémur", "Il femore", "Das Oberschenkelbein", "大腿骨", "عظم الفخذ", "股骨", "Het dijbeen", "O fêmur", "Lårbenet", "Бедренная кость", "Kość udowa", "대퇴골"), tt("Dans la cuisse, de la hanche jusqu'au grasset.", "In the thigh, from the hip to the stifle.", "En el muslo, desde la cadera hasta la babilla.", "Nella coscia, dall'anca fino alla grassella.", "Im Oberschenkel, von der Hüfte bis zum Kniegelenk.", "大腿の中、股関節から後膝（スタイフル）まで。", "في الفخذ، من الورك حتى مفصل الرضفة.", "位于大腿，从髋部到后膝。", "In de dij, van de heup tot de knie van het achterbeen.", "Na coxa, da anca até à soldra.", "I låret, från höften till knäleden.", "В бедре, от тазобедренного до коленного сустава.", "W udzie, od biodra do stawu kolanowego.", "넓적다리 안, 고관절에서 슬관절까지.")],
      ["s-gras", 975, 515, tt("Le grasset", "The stifle", "La babilla", "La grassella", "Das Kniegelenk", "後膝（スタイフル）", "مفصل الرضفة", "后膝", "De knie van het achterbeen", "A soldra", "Knäleden", "Коленный сустав", "Staw kolanowy", "슬관절(스타이플)"), tt("À l'avant du postérieur, entre le fémur et le tibia.", "At the front of the hind leg, between the femur and the tibia.", "En la parte delantera del posterior, entre el fémur y la tibia.", "Sul davanti del posteriore, tra il femore e la tibia.", "Vorne am Hinterbein, zwischen Oberschenkelbein und Schienbein.", "後肢の前側、大腿骨と脛骨のあいだ。", "في مقدّمة القائمة الخلفية، بين عظم الفخذ وعظم الظنبوب.", "位于后肢前侧，在股骨和胫骨之间。", "Aan de voorkant van het achterbeen, tussen het dijbeen en het scheenbeen.", "Na frente do posterior, entre o fêmur e a tíbia.", "Framtill på bakbenet, mellan lårbenet och underbenet.", "Спереди на задней ноге, между бедренной и большеберцовой костью.", "Z przodu kończyny tylnej, między kością udową a piszczelą.", "뒷다리 앞쪽, 대퇴골과 경골 사이.")],
      ["s-tib", 1060, 600, tt("Le tibia", "The tibia", "La tibia", "La tibia", "Das Schienbein", "脛骨", "عظم الظنبوب", "胫骨", "Het scheenbeen", "A tíbia", "Underbenet (tibia)", "Большеберцовая кость", "Piszczel", "경골"), tt("Dans la jambe, entre le grasset et le jarret.", "In the gaskin, between the stifle and the hock.", "En la pierna, entre la babilla y el corvejón.", "Nella gamba, tra la grassella e il garretto.", "Im Unterschenkel, zwischen Kniegelenk und Sprunggelenk.", "下腿の中、後膝と飛節のあいだ。", "في الساق، بين مفصل الرضفة والعرقوب.", "位于小腿，在后膝和跗关节之间。", "In het onderbeen, tussen de knie en de sprong.", "Na perna, entre a soldra e o jarrete.", "Mellan knäleden och hasen.", "В голени, между коленным и скакательным суставом.", "W podudziu, między stawem kolanowym a skokowym.", "정강이 안, 슬관절과 비절 사이.")],
      ["s-jar", 1152, 688, tt("Les os du jarret", "The hock bones", "Los huesos del corvejón", "Le ossa del garretto", "Die Knochen des Sprunggelenks", "飛節の骨", "عظام العرقوب", "跗关节的骨骼", "De botten van de sprong", "Os ossos do jarrete", "Benen i hasen", "Кости скакательного сустава", "Kości stawu skokowego", "비절의 뼈"), tt("Au milieu du postérieur, entre le tibia et le canon.", "In the middle of the hind leg, between the tibia and the cannon.", "En medio del posterior, entre la tibia y la caña.", "A metà del posteriore, tra la tibia e lo stinco.", "In der Mitte des Hinterbeins, zwischen Schienbein und Röhrbein.", "後肢の中ほど、脛骨と管のあいだ。", "في منتصف القائمة الخلفية، بين عظم الظنبوب والمدماك.", "位于后肢中部，在胫骨和炮骨之间。", "Halverwege het achterbeen, tussen het scheenbeen en de pijp.", "A meio do posterior, entre a tíbia e a canela.", "Mitt på bakbenet, mellan underbenet och skenbenet.", "В середине задней ноги, между большеберцовой костью и плюсной.", "W połowie kończyny tylnej, między piszczelą a nadpęciem.", "뒷다리 중간, 경골과 관골 사이.")]
